"""Shared figure style. Every figure in the atlas is regenerated by a script in scripts/."""
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402

FIG = Path(__file__).resolve().parents[1] / "results" / "figures"

# categorical palette for Betti "types" (validated colour-blind safe order)
TYPE_COLORS = ["#2a6fdb", "#e0832b", "#2f9e6e", "#c2417a", "#7a5cc7", "#8a8f98", "#b8a032"]


def style():
    plt.rcParams.update({
        "font.size": 9, "axes.titlesize": 10, "axes.labelsize": 9,
        "axes.spines.top": False, "axes.spines.right": False,
        "figure.dpi": 130, "savefig.dpi": 220, "savefig.bbox": "tight",
        "font.family": "serif", "mathtext.fontset": "cm",
    })
    return plt


def save(fig, name):
    FIG.mkdir(parents=True, exist_ok=True)
    fig.savefig(FIG / f"{name}.pdf")
    fig.savefig(FIG / f"{name}.png")
    plt.close(fig)
    print("saved", FIG / f"{name}.png")


def betti_label(b):
    """Readable name of a Betti vector, e.g. [1,0,1,0] -> 'b0=1 b2=1'."""
    return " ".join(f"β{q}={v}" for q, v in enumerate(b) if v)
